      const prop = choose(rng, [['has the highest boiling point', 'I', 'The larger the halogen, the stronger the van der Waals forces.'], ['is the most reactive in nucleophilic substitution', 'I', 'C-I is the weakest bond and I<sup>&minus;</sup> is the best leaving group.'], ['has the strongest C-X bond', 'F', 'The C-F bond is the shortest and strongest.'], ['has the shortest C-X bond', 'F', 'Fluorine is the smallest halogen.'], ['has the highest density', 'I', 'Density rises with the atomic mass of the halogen.'], ['has the lowest boiling point', 'F', 'Fluorine is the smallest, giving the weakest dispersion forces.']]);
      const all = ['F', 'Cl', 'Br', 'I'].map((x) => F(r + x)); const right = F(r + prop[1]);
