      const sums = new Set(); for (let i = 0; i < k; i++) for (let j = i; j < k; j++) sums.add(chosen[i] + chosen[j]);
      const names = chosen.map((c) => `${c === 1 ? 'CH3' : 'CH3(CH2)' + (c - 1)}Br`).map(F);
      return { q: `A mixture of the straight-chain alkyl bromides ${names.join(', ')} (with ${chosen.join(', ')} carbon atoms) is treated with sodium in dry ether. How many different alkanes are formed in all?`, answer: sums.size, tol: 0, chosen,
        sol: `<p>Each pair (including a bromide with itself) can couple: ${k}(${k} + 1)/2 = ${k * (k + 1) / 2} couplings. A coupling of chains with a and b carbons gives the n-alkane with a + b carbons, so couplings with the same sum give the same alkane.</p><p>Sums of pairs: ${[...sums].sort((a, b) => a - b).join(', ')}. Number of different alkanes = <b>${sums.size}</b>.</p>`, trap: 'Different couplings can give the same product.' };
